<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api, errorMessage } from '../api.js'
import { useAuth } from '../stores/auth.js'
import { browserZone, localInput, localToInstant } from '../time.js'
const props = defineProps({ id: [String, Number] }), router = useRouter(), auth = useAuth()
const editing = computed(() => Boolean(props.id)), busy = ref(false), loading = ref(false), error = ref('')
const zone = auth.user?.timeZone || browserZone()
const form = reactive({ title: '', recipientEmail: auth.user?.email || '', recipientName: auth.user?.displayName || '', message: '', timeZone: zone, localTime: localInput(new Date(Date.now() + 3600000).toISOString(), zone), version: null })
async function load() { if (!editing.value) return; loading.value = true; try { const { data } = await api.get(`/reminders/${props.id}`); if (!['PENDING', 'RETRY'].includes(data.status)) throw new Error('This reminder can no longer be edited.'); Object.assign(form, data, { localTime: localInput(data.scheduledAt, data.timeZone) }) } catch (e) { error.value = e.response ? errorMessage(e) : e.message } finally { loading.value = false } }
async function submit() { busy.value = true; error.value = ''; try { const scheduledAt = localToInstant(form.localTime, form.timeZone); if (Date.parse(scheduledAt) <= Date.now()) throw new Error('Choose a future date and time.'); const body = { title: form.title, recipientEmail: form.recipientEmail, recipientName: form.recipientName || null, message: form.message, timeZone: form.timeZone, scheduledAt, version: form.version }; if (editing.value) await api.put(`/reminders/${props.id}`, body); else await api.post('/reminders', body); router.push('/reminders') } catch (e) { error.value = e.response ? errorMessage(e) : e.message } finally { busy.value = false } }
onMounted(load)
</script>
<template><div class="page-heading"><div><span class="eyebrow">MAKE SPACE FOR WHAT MATTERS</span><h1>{{ editing ? 'A change of plans.' : 'One less thing to remember.' }}</h1><p>{{ editing ? 'Update your reminder before processing begins.' : 'Pick a moment. Write a note. We’ll send the nudge.' }}</p></div><RouterLink to="/reminders" class="button ghost">← Back to reminders</RouterLink></div><div class="editor-layout"><form class="panel editor-form" @submit.prevent="submit"><div class="panel-heading"><div><h2>{{ editing ? 'Edit reminder' : 'Reminder details' }}</h2><p>Small details make a thoughtful reminder.</p></div></div><p v-if="error" class="notice error" role="alert">{{ error }} <button v-if="editing" type="button" class="text-button" @click="load">Reload reminder</button></p><p v-if="loading" role="status">Loading reminder…</p><fieldset :disabled="loading || busy"><label>What’s the occasion?<input v-model.trim="form.title" required maxlength="200" placeholder="e.g. Renew my insurance"></label><div class="form-grid"><label>Recipient email<input v-model.trim="form.recipientEmail" type="email" required maxlength="254" placeholder="you@example.com"></label><label>Recipient name <span class="optional">optional</span><input v-model.trim="form.recipientName" maxlength="100" placeholder="A friendly name"></label></div><label>Your message<textarea v-model="form.message" required maxlength="10000" rows="6" placeholder="A helpful note for your future self…"></textarea><small class="field-help right">{{ form.message.length }} / 10,000</small></label><div class="form-grid"><label>Date & time<input v-model="form.localTime" type="datetime-local" required></label><label>Time zone<input v-model.trim="form.timeZone" required maxlength="64" list="time-zones"><datalist id="time-zones"><option>Asia/Kolkata</option><option>UTC</option><option>Europe/London</option><option>America/New_York</option><option>America/Los_Angeles</option><option>Asia/Singapore</option><option>Australia/Sydney</option></datalist></label></div><p class="field-help">The selected local time is converted to UTC. Ambiguous or skipped daylight-saving times are rejected.</p><div class="form-actions"><RouterLink to="/reminders" class="button ghost">Cancel</RouterLink><button class="button primary" :disabled="busy || loading">{{ busy ? 'Saving…' : editing ? 'Save changes →' : 'Schedule reminder →' }}</button></div></fieldset></form><aside><div class="tip-card"><span class="tip-symbol">✦</span><h3>A thoughtful little nudge.</h3><p>Your reminder is saved on the server. You can close this page; it will still run at the scheduled time.</p><hr><strong>Every attempt has a story.</strong><p>Definite sending failures are retried with increasing delays. Uncertain outcomes stop for review to reduce duplicate emails.</p><RouterLink to="/history" class="text-link">Explore email history ↗</RouterLink></div></aside></div></template>
